function fmt(value, unit) {
  const rounded = Math.abs(value) >= 1e3 ? Math.round(value) : Math.round(value * 100) / 100;
  return unit ? `${rounded}${unit}` : String(rounded);
}
function seriesLines(data) {
  const { labels, series, unit } = data;
  const lines = labels.slice(0, MAX_LINES).map((label, index) => {
    const cells = series.map((entry) => `${entry.name}=${fmt(entry.values[index] ?? 0, unit)}`);
    return `- ${label}: ${cells.join(", ")}`;
  });
  if (labels.length > MAX_LINES) lines.push(`- \u2026 (${labels.length - MAX_LINES} more)`);
  return lines;
}
function sliceLines(data) {
  const total = data.slices.reduce((sum, slice) => sum + Math.max(0, slice.value), 0);
  return data.slices.map((slice) => {
    const share = total > 0 ? Math.round(Math.max(0, slice.value) / total * 100) : 0;
    return `- ${slice.label}: ${fmt(slice.value, data.unit)} (${share}%)`;
  });
}
function scatterLines(data) {
  const { points } = data;
  const xs = points.map((point) => point.x);
  const ys = points.map((point) => point.y);
  const lines = [
    `- ${points.length} points; x ${fmt(Math.min(...xs))}..${fmt(Math.max(...xs))}; y ${fmt(Math.min(...ys))}..${fmt(Math.max(...ys))}`
  ];
  points.slice(0, MAX_LINES).forEach((point) => {
    lines.push(`- (${fmt(point.x)}, ${fmt(point.y)})${point.label ? ` ${point.label}` : ""}`);
  });
  if (points.length > MAX_LINES) lines.push(`- \u2026 (${points.length - MAX_LINES} more)`);
  return lines;
}
function compareLines(data) {
  const { columns, rows } = data;
  const head = `| ${columns.join(" | ")} |`;
  const rule = `| ${columns.map(() => "---").join(" | ")} |`;
  const body = rows.slice(0, MAX_LINES).map((row) => `| ${columns.map((_, i) => row[i] ?? "").join(" | ")} |`);
  if (rows.length > MAX_LINES) body.push(`| \u2026 (${rows.length - MAX_LINES} more rows) |`);
  return [head, rule, ...body];
}
function timelineLines(data) {
  return data.items.map((item) => `- ${item.at ? `[${item.at}] ` : ""}${item.label}${item.detail ? ` \u2014 ${item.detail}` : ""}`);
}
function ganttLines(data) {
  return data.tasks.map((task) => `- ${task.label}: ${fmt(task.start, data.unit)}\u2013${fmt(task.end, data.unit)}`);
}
function waterfallLines(data) {
  let running = 0;
  const lines = data.labels.map((label, index) => {
    const value = data.values[index] ?? 0;
    running += value;
    const sign = value > 0 ? "+" : "";
    return `- ${label}: ${sign}${fmt(value, data.unit)} (\u2192 ${fmt(running, data.unit)})`;
  });
  lines.push(`- ${data.totalLabel ?? "Total"}: ${fmt(running, data.unit)}`);
  return lines;
}
function heatmapLines(data) {
  const head = `| | ${data.columns.join(" | ")} |`;
  const rule = `| --- | ${data.columns.map(() => "---").join(" | ")} |`;
  const body = data.rows.slice(0, MAX_LINES).map((row, rowIndex) => {
    const cells = data.columns.map((_, columnIndex) => {
      const value = data.values[rowIndex]?.[columnIndex];
      return value === void 0 ? "" : fmt(value, data.unit);
    });
    return `| ${row} | ${cells.join(" | ")} |`;
  });
  if (data.rows.length > MAX_LINES) body.push(`| \u2026 | (${data.rows.length - MAX_LINES} more rows) |`);
  return [head, rule, ...body];
}
function flowLines(data) {
  const byId = new Map(data.nodes.map((node) => [node.id, node]));
  const lines = data.nodes.slice(0, MAX_LINES).map((node) => `- ${node.label}${node.detail ? ` \u2014 ${node.detail}` : ""}`);
  if (data.nodes.length > MAX_LINES) lines.push(`- \u2026 (${data.nodes.length - MAX_LINES} more nodes)`);
  if (data.edges.length > 0) {
    lines.push("", ...data.edges.slice(0, MAX_LINES).map((edge) => `- ${byId.get(edge.from)?.label ?? edge.from} \u2192 ${byId.get(edge.to)?.label ?? edge.to}${edge.label ? ` (${edge.label})` : ""}`));
  }
  return lines;
}
function curveLines(data) {
  const lines = [];
  if (data.auc !== void 0) lines.push(`- AUC: ${fmt(data.auc)}`);
  lines.push(...data.points.slice(0, MAX_LINES).map((point) => `- (${fmt(point.x)}, ${fmt(point.y)})${point.label ? ` ${point.label}` : ""}`));
  if (data.points.length > MAX_LINES) lines.push(`- \u2026 (${data.points.length - MAX_LINES} more)`);
  return lines;
}
function confusionLines(data) {
  const { labels, matrix } = data;
  const total = matrix.flat().reduce((sum, value) => sum + value, 0);
  const correct = matrix.reduce((sum, row, index) => sum + (row[index] ?? 0), 0);
  const accuracy = total > 0 ? correct / total : 0;
  const lines = [`- accuracy: ${Math.round(accuracy * 1e3) / 10}% (${correct}/${total})`];
  labels.forEach((label, index) => {
    const row = matrix[index] ?? [];
    const rowTotal = row.reduce((sum, value) => sum + value, 0);
    const recall = rowTotal > 0 ? (row[index] ?? 0) / rowTotal : 0;
    lines.push(`- ${label}: recall ${Math.round(recall * 1e3) / 10}% (n=${rowTotal})`);
  });
  return lines;
}
function histogramLines(data) {
  return data.bins.map((bin) => `- [${fmt(bin.start)}, ${fmt(bin.end)}): ${bin.count}`);
}
function leaderboardLines(data) {
  const head = `| model | ${data.metrics.map((metric) => metric.label).join(" | ")} |`;
  const rule = `| --- | ${data.metrics.map(() => "---").join(" | ")} |`;
  const best = data.metrics.map((metric, index) => {
    const values = data.rows.map((row) => row.values[index] ?? 0);
    return metric.better === "down" ? Math.min(...values) : Math.max(...values);
  });
  const body = data.rows.map((row) => {
    const cells = data.metrics.map((metric, index) => {
      const value = row.values[index] ?? 0;
      const text = `${metric.better === "down" ? "" : ""}${fmt(value, metric.unit)}`;
      return value === best[index] ? `**${text}**` : text;
    });
    return `| ${row.name} | ${cells.join(" | ")} |`;
  });
  return [head, rule, ...body];
}
function metricLines(data) {
  return data.items.map((item) => {
    const arrow = item.trend === "up" ? "\u2191" : item.trend === "down" ? "\u2193" : item.trend === "flat" ? "\u2192" : "";
    const delta = item.delta ? ` (${arrow}${item.delta})` : "";
    return `- ${item.label}: ${item.value}${data.unit ?? ""}${delta}`;
  });
}
var BODIES = {
  bar: seriesLines,
  line: seriesLines,
  area: seriesLines,
  radar: seriesLines,
  pie: sliceLines,
  doughnut: sliceLines,
  scatter: scatterLines,
  compare: compareLines,
  timeline: timelineLines,
  gantt: ganttLines,
  metrics: metricLines,
  waterfall: waterfallLines,
  heatmap: heatmapLines,
  flow: flowLines,
  curve: curveLines,
  confusion: confusionLines,
  histogram: histogramLines,
  leaderboard: leaderboardLines
};
function renderText(spec) {
  const lines = [spec.title];
  if (spec.subtitle) lines.push(spec.subtitle);
  lines.push(...BODIES[spec.kind](spec.data));
  if (spec.note) lines.push("", spec.note);
  return lines.join("\n");
}

// src/host/index.js
var name = "inline-visuals";
var inject = ["tools"];
var DESCRIPTION = "Render a small, self-contained visual inside the conversation. Kinds: bar, line, area (chart), pie, doughnut, scatter, radar, waterfall; curve (ROC/PR), histogram, confusion (matrix), leaderboard; compare (table), timeline, gantt, heatmap, metrics (KPI tiles), flow (DAG). Use `style` for presentation variants (horizontal/stacked bars, stepped lines, palettes, height, data labels, legends). To revise an existing visual, call edit_visual with a partial patch instead of re-sending the whole spec.";
var DATA_DESCRIPTION = 'bar/line/area/radar: { labels: string[], series: [{ name, values: number[] }], unit?: string }. pie/doughnut: { slices: [{ label, value }], unit?: string }. scatter: { points: [{ x, y, label? }], xLabel?, yLabel? }. waterfall: { labels: string[], values: number[], unit?, totalLabel? } (values are deltas). heatmap: { rows: string[], columns: string[], values: number[][], unit? }. compare: { columns: string[], rows: string[][] }. timeline: { items: [{ at?, label, detail? }] }. gantt: { tasks: [{ label, start, end, group? }], unit?: string }. metrics: { items: [{ label, value, delta?, trend?: "up"|"down"|"flat" }], unit?: string }.';
var STYLE_DESCRIPTION = "Presentation-only options. palette: default|mono|cool|warm|success. legend: auto|bottom|top|none. height: 160\u2013420. density: compact|normal. values: draw data labels. grid: show grid lines. orientation: vertical|horizontal (bar). stacked: stack series (bar/line/area). curve: linear|smooth|step (line/area). points: draw point markers. trendLine: linear fit (scatter). xScale/yScale: linear|log (log axes for training curves and scaling laws). smoothing: 0\u20130.9 EMA smoothing for noisy curves. errorBars: draw errors[] whiskers. baseline: draw the y=x diagonal (ROC).";
var STYLE_PARAMETERS = {
  type: "object",
  additionalProperties: false,
  description: STYLE_DESCRIPTION,
  properties: {
    palette: { type: "string", enum: PALETTES },
    legend: { type: "string", enum: ["auto", "bottom", "top", "none"] },
    height: { type: "integer", description: "Card chart height in px (160\u2013420)." },
    density: { type: "string", enum: ["compact", "normal"] },
    values: { type: "boolean" },
    grid: { type: "boolean" },
    orientation: { type: "string", enum: ["vertical", "horizontal"] },
    stacked: { type: "boolean" },
    curve: { type: "string", enum: ["linear", "smooth", "step"] },
    points: { type: "boolean" },
    trendLine: { type: "boolean" },
    xScale: { type: "string", enum: ["linear", "log"] },
    yScale: { type: "string", enum: ["linear", "log"] },
    smoothing: { type: "number", description: "EMA smoothing 0\u20130.9 for line/area series." },
    errorBars: { type: "boolean" },
    baseline: { type: "boolean" }
  }
};
function apply(ctx) {
  ctx.effect(() => ctx.tools.register({
    name: "show_visual",
    description: DESCRIPTION,
    parameters: {
      type: "object",
      additionalProperties: false,
      required: ["kind", "title", "data"],
      properties: {
        kind: { type: "string", enum: KINDS, description: "Visual form to render." },
        title: { type: "string", description: "Short title shown above the visual." },
        subtitle: { type: "string", description: "Optional secondary line." },
        note: { type: "string", description: "Optional one-sentence takeaway shown below." },
        style: STYLE_PARAMETERS,
        data: { type: "object", description: DATA_DESCRIPTION }
      }
    },
    output: {
      // The canonical value is the normalized spec; clipping lives in execute().
      schema: { type: "object" },
      // Text fallback for clients without the card renderer (and for logs/exports).
      render: (_args, value) => [{ type: "text", text: renderText(value) }],
      // Persisted on tool/result so the Client renders the same visual on replay.
      presentationMeta: (_args, value) => value
    },
    async execute(args) {
      return normalize(args);
    },
    presentCall(args) {
      const kind = args !== null && typeof args === "object" && typeof args.kind === "string" ? args.kind : "visual";
      return { card: "generic", title: `Render ${kind}`, kind: "other", rawInput: args };
    }
  }), "inline-visuals: show_visual tool");
  ctx.effect(() => ctx.tools.register({
    name: "edit_visual",
    description: "Revise the most recent visual in this session (or one specific call id) by patching its spec. Pass only the fields to change: nested objects merge, arrays replace, null deletes a key. Use this instead of calling show_visual again with the entire spec.",
    parameters: {
      type: "object",
      additionalProperties: false,
      required: ["patch"],
      properties: {
        patch: {
          type: "object",
          description: 'Partial spec: any of kind, title, subtitle, note, style or data. Example: { "style": { "orientation": "horizontal", "stacked": true } } or { "data": { "labels": [...] } }.'
        },
        target: {
          type: "string",
          description: "Optional tool call id of the visual to edit; omit to edit the latest visual."
        }
      }
    },
    output: {
      schema: { type: "object" },
      render: (_args, value) => [{ type: "text", text: renderText(value) }],
      presentationMeta: (_args, value) => value
    },
    async execute(args, exec) {
      if (!exec.agent) throw new Error("edit_visual requires an owning agent session");
      const previous = findPreviousSpec(exec.agent.session, args.target);
      if (previous === void 0) {
        throw new Error("no previous visual in this session; call show_visual first");
      }
      return normalize(applyPatch(previous, args.patch));
    },
    presentCall(args) {
      return { card: "generic", title: "Edit visual", kind: "other", rawInput: args };
    }
  }), "inline-visuals: edit_visual tool");
}
export {
  apply,
  inject,
  name
};
